import sympy as sp, math, itertools
x,y,a,b,k,n=sp.symbols('x y a b k n'); R=sp.Rational; C=math.comb; cl=math.isclose; s2,s3=sp.sqrt(2),sp.sqrt(3)
co=lambda e,v,p: sp.Poly(sp.expand(e),v).coeff_monomial(v**p)
