assert abs((3-R(1,2))/(1+3*R(1,2)))==1 and sp.solve((9-a)/(5-2)-3,a)==[0] and sl((2,3),(6,-1))==-1 and sl((3,-4),(5,0))==2 and sl((1,2),(4,3))==sl((2,5),(5,6))==R(1,3) and sl((4,3),(5,6))==3 and sl((1,2),(5,6))*sl((4,3),(2,5))==-1
